def parse_duration(s):
    """'30s' -> 30, '5m' -> 300, '2h' -> 7200, '1d' -> 86400"""
    if s.endswith("s"):
        return int(s[:-1])
    if s.endswith("m"):
        return int(s[:-1]) * 60
    if s.endswith("h"):
        return int(s[:-1]) * 3600
    if s.endswith("d"):
        return int(s[:-1]) * 86400
    raise ValueError(f"bad duration: {s}")
